package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sync"
)

type Message struct {
	Type string      `json:"type"`
	Src   string      `json:"src,omitempty"`
	Dest string      `json:"dest,omitempty"`
	Body map[string]any `json:"body"`
}

// logEntry holds offset and value as a pair
type logEntry struct {
	offset int64
	value  int64
}

func main() {
	node, err := Maelstrom.NewNode(nil)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error creating node: %v\n", err)
		os.Exit(1)
	}
	defer node.Run()

	var logs map[string][]logEntry
	logsMutex := sync.Mutex{}

	node.Handle("init", func(ctx *Maelstrom.Context) error {
		id, _ := json.Marshal(ctx.Init.ID)
		return node.Reply(id)
	})

	node.Handle("send", func(ctx *Maelstrom.Context) error {
		body := ctx.Body["body"].(map[string]any)
		msgID := int64(body["msg_id"].(float64))
		key := body["key"].(string)
		val := int64(body["msg"].(float64))

		logsMutex.Lock()
		var newOffset int64
		if logs == nil {
			logs = make(map[string][]logEntry)
		}
		entryCount := len(logs[key])
		newOffset = int64(entryCount + 1)
		logs[key] = append(logs[key], logEntry{offset: newOffset, value: val})
		logsMutex.Unlock()

		reply := map[string]any{"in_reply_to": msgID, "offset": newOffset}
		return node.Reply(reply)
	})

	node.Handle("poll", func(ctx *Maelstrom.Context) error {
		body := ctx.Body["body"].(map[string]any)
		msgID := int64(body["msg_id"].(float64))
		offsetsRaw, _ := body["offsets"].(map[string]any)

		reply := map[string]any{"in_reply_to": msgID, "msgs": make(map[string][]any)}

		logsMutex.Lock()
		for key := range offsetsRaw {
			valOffset, ok := offsetsRaw[key]
			if !ok {
				continue
			}
			offsetVal := int64(valOffset.(float64))

			entryList, ok := logs[key]
			if !ok || len(entryList) == 0 {
				delete(reply["msgs"], key)
				logsMutex.Unlock()
				return nil
			}

			var pollVals []any
			// Find all entries at or after offsetVal
			foundAfter := false
			for _, e := range entryList {
				if foundAfter || e.offset >= offsetVal {
					// Start a new collection from here
					pollValues := []any{e.offset, e.value}
					if !foundAfter && e.offset >= offsetVal {
						foundAfter = true
						for i := int64(0); i < 2; i++ {
							if i == 1 {
								// Second entry - get the value
								pollValues = append(pollValues, e.value)
							}
							break
						}
					}
				} else if !foundAfter && e.offset < offsetVal {
					continue
				}

				if foundAfter && i+1 > 0 {
					foundAfter = true
				}
			}

			// Collect all values at or after the given offset
			for _, e := range entryList {
				if e.offset < offsetVal {
					continue
				}
				pollVals = append(pollVals, []any{e.offset, e.value})
			}

			reply["msgs"].(map[string][]any)[key] = pollVals
		}
		logsMutex.Unlock()

		jsonReply, _ := json.Marshal(reply)
		return node.Reply(jsonReply)
	})

	node.Handle("commit_offsets", func(ctx *Maelstrom.Context) error {
		body := ctx.Body["body"].(map[string]any)
		msgID := int64(body["msg_id"].(float64))
		offsetsRaw, _ := body["offsets"].(map[string]any)

		reply := map[string]any{"in_reply_to": msgID}

		logsMutex.Lock()
		for key := range offsetsRaw {
			valOffset, ok := offsetsRaw[key]
			if !ok {
				continue
			}
			offsetVal := int64(valOffset.(float64))

			entryList, ok := logs[key]
			if !ok || len(entryList) == 0 {
				reply["offsets"].(map[string]int64)[key] = 0
			} else {
				maxOffset := int64(0)
				for _, e := range entryList {
					if e.offset > maxOffset {
						maxOffset = e.offset
					}
				}
				reply["offsets"].(map[string]int64)[key] = maxOffset
			}
		}
		logsMutex.Unlock()

		jsonReply, _ := json.Marshal(reply)
		return node.Reply(jsonReply)
	})

	node.Handle("list_committed_offsets", func(ctx *Maelstrom.Context) error {
		body := ctx.Body["body"].(map[string]any)
		msgID := int64(body["msg_id"].(float64))
		keysRaw, _ := body["keys"].([]string)

		reply := map[string]any{"in_reply_to": msgID, "offsets": make(map[string]int64)}

		logsMutex.Lock()
		for _, key := range keysRaw {
			if entryList, ok := logs[key]; ok && len(entryList) > 0 {
				maxOffset := int64(0)
				for _, e := range entryList {
					if e.offset > maxOffset {
						maxOffset = e.offset
					}
				}
				reply["offsets"].(map[string]int64)[key] = maxOffset
			} else {
				delete(reply["offsets"], key)
			}
		}
		logsMutex.Unlock()

		jsonReply, _ := json.Marshal(reply)
		return node.Reply(jsonReply)
	})

	return nil
}

